<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\Tenant\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Access\Tenant\Domain\ValueObject\TenantNameVO;

trait TenantNameAccessor
{
    private TenantNameVO $_name;
    public function getName(): string
    {
        return $this->_name->value();
    }
    public function name(): TenantNameVO
    {
        return $this->_name;
    }
    public function isNameChanged(?self $original = null): bool
    {
        return !$this->_name->equals($original?->_name);
    }
    public function withName(TenantNameVO|string $name): self
    {
        $copy = clone $this;
        $copy->_name = TenantNameVO::from($name);
        return $copy;
    }
}
